def parse_grid(text,label):
 m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n',text)
 if not m:return None
 R,C=map(int,m.groups()); start=m.end(); rows=[]
 for line in text[start:].splitlines():
