 return rows

def comps(g,color,conn=4):
 R=len(g);C=len(g[0]);seen=set();out=[]
 for r in range(R):
  for x in range(C):
   if g[r][x]!=color or (r,x) in seen:continue
   q=[(r,x)];seen.add((r,x)); cells=[]
   for a,b in q:
    cells.append((a,b))
    for da,db in ([(1,0),(-1,0),(0,1),(0,-1)] if conn==4 else [(i,j) for i in [-1,0,1] for j in [-1,0,1] if i or j]):
