def norm(cells):
 r0=min(r for r,c in cells); c0=min(c for r,c in cells)
 return frozenset((r-r0,c-c0) for r,c in cells)
def bbox(cells):
 return (min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells))
